// O(n²): every zero shifts the whole tail
public void MoveZeroes(int[] nums) {
    int n = nums.Length, zeros = 0;
    for (int i = 0; i < n - zeros; ) {
        if (nums[i] != 0) { i++; continue; }
        Array.Copy(nums, i + 1, nums, i, n - zeros - i - 1); // tail up to the zeroes, left by 1
        nums[n - zeros - 1] = 0;
        zeros++;
    }
}

