// order does not matter: O(1) per removal, no shifting
for (int i = enemies.Count - 1; i >= 0; i--) {
    if (!enemies[i].IsDead) continue;
    int last = enemies.Count - 1;
    enemies[i] = enemies[last];   // the last one takes the dead one's place
    enemies.RemoveAt(last);       // removing from the end shifts nothing
}
